    /**
     * Checks if a user is a member of any contract in a project and returns their organization.
     *
     * @param projectId The project ID to check within.
     * @param userId The user ID to check for.
     * @return A map containing membership status and organization name.
     */
    public Map<String, Object> getProjectMembership(String projectId, String userId) {
        String qlString = "SELECT cm.organizationName from ContractMember cm " +
                "WHERE cm.contract.projectId = :projectId AND cm.userId = :userId";
        Query query = entityManager.createQuery(qlString);
        query.setParameter("projectId", UUID.fromString(projectId));
        query.setParameter("userId", UUID.fromString(userId));
        query.setMaxResults(1);
        List<String> results = query.getResultList();

        Map<String, Object> response = new HashMap<>();
        if (results.isEmpty() || results.get(0) == null) {
            response.put("isMember", false);
            response.put("organizationName", null);
        } else {
            response.put("isMember", true);
            response.put("organizationName", results.get(0));
        }
        return response;
    }

    /**
     * Performs the contract creation operation.
     *
     * @param contract      The contract is being created.
     * @param authContext   saga auth context
     * @return A newly created contract object.
     */

    public Contract addContract(Contract contract, AuthContext authContext) {

        var savedContract = contractRepository.save(contract);
        // event publish
        var payload = new Payload();
        payload.set(CONTRACT, savedContract);

        events.raiseEvent(EventType.EVENT_KEY_CONTRACT_CREATED, savedContract.getId(), payload,
                authContext.getUserName(), authContext.getOtdsUserId(), savedContract.getProjectId(),
                authContext.getSubscriptionId(), authContext.getTenantId());

        log.debug("contract created with id [{}] in project [{}]", savedContract.getId(), savedContract.getProjectId());
        return savedContract;
    }

    public Contract updateContract(Contract contract) throws DuplicateEntryException {
    	checkDuplicateContractName(contract);
        var savedContract = contractRepository.save(contract);
        log.debug("contract updated with id [{}] in project [{}]", savedContract.getId(), savedContract.getProjectId());
        return savedContract;
    }

    private void checkDuplicateContractName(Contract contract) throws DuplicateEntryException {
    	List<Contract> contracts = getContractsByProjectId(contract.getProjectId());
    	if (contracts.stream().anyMatch(c -> c.getName().equalsIgnoreCase(contract.getName()) && !c.getId().equals(contract.getId()))) {
    		throw new DuplicateEntryException("Contract with same name already exist in the project");
    	}
    }

    public void deleteContractDetails(UUID contractId) throws ObjectNotFoundException, IOException, RequiredFieldsMissingException {
        // check if contract is present for the contract ID, if not present it throws ObjectNotFoundException
        getContractById(contractId);

        // delete contract settings & settings content
        settingsService.deleteSettings(SettingsEnum.ObjectType.contract.name(), contractId);

        // delete contract level user preferences
        userPreferencesService.deleteUserPreferences(SettingsEnum.ObjectType.contract.name(), contractId.toString());

        // delete contract members
        contractMemberDeleteService.deleteContractMembers(contractId);

        // Finally, delete contract
        deleteContract(contractId);
    }

    /**
     * Deletes a contract
     *
     * @param id Contract id
     */
    public void deleteContract(UUID id) {
        contractRepository.deleteById(id);
    }

    public List<Contract> getAllContracts(FilterContractInput filter) {
        PageRequestInput pageRequest = PageRequestInput.getDefaultPageRequestInput();

        List<Contract> allContracts = new ArrayList<>();
        List<Contract> currentContracts;
        do {
            currentContracts = getContracts(filter, pageRequest);
            allContracts.addAll(currentContracts);
            pageRequest.setPage(pageRequest.getPage() + 1);
        } while (currentContracts.size() == pageRequest.getSize());
        return allContracts;
    }

    /**
     * get all contracts
     *
     * @param filter return Contracts
     */
    public List<Contract> getContracts(FilterContractInput filter, PageRequestInput pageRequest) throws InvalidSubscriptionException {
        pageRequest = PageRequestInput.getEffectivePageRequestInput(pageRequest);

        String baseQueryStr = filter.isIncludeProjectDetails()
                ? CONTRACTS_WITH_PROJECT_QUERY
                : CONTRACTS_BASE_QUERY;

        //Form the query with all required parameters.
        Query contractQuery = generateContractsQuery(filter, baseQueryStr, pageRequest.getOrderByClause());

        int pageNumber = pageRequest.getPage();
        int pageSize = pageRequest.getSize();
        //Throughout the service, the pagination starts from index 1 as one-index-parameters is enabled.
        //Hence the below logic applies the same one index pagination for contracts as well.
        contractQuery.setFirstResult((pageNumber <= 0 ? 0 : pageNumber - 1) * pageSize);
        contractQuery.setMaxResults(pageSize);
        return getContracts(contractQuery, filter);
    }

    @NotNull
    private List<Contract> getContracts(Query contractQuery, FilterContractInput filter) {
        List<Object[]> results = contractQuery.getResultList();
        List<Contract> contracts = new ArrayList<>();
        Map<UUID, Map<String, String>> settingsMap = filter.isIncludeSettings() ? getContractSettingsMap(results) : Collections.EMPTY_MAP;
        results.stream().forEach(result -> {
            Contract contract = new Contract();
            contract.setId((UUID) result[0]);
            contract.setName((String) result[1]);
            contract.setCode((String) result[2]);
            contract.setDescription((String) result[3]);
            contract.setKeywords((List<String>) result[4]);
            contract.setContractNumber((String) result[5]);
            contract.setPoNumber((String) result[6]);
            contract.setOwner((String) result[7]);
            contract.setContractor((String) result[8]);
            contract.setContractType((String) result[9]);
            contract.setSignedOn((Timestamp) result[10]);
            contract.setStartsOn((Timestamp) result[11]);
            contract.setExpiresOn((Timestamp) result[12]);
            contract.setCreatedBy((UUID) result[13]);
            contract.setModifiedBy((UUID) result[14]);
            contract.setProjectId((UUID) result[15]);
            contract.setCreatedOn((OffsetDateTime) result[16]);
            contract.setModifiedOn((OffsetDateTime) result[17]);
            contract.setLegacyId(result[18] != null ? (String) result[18] : "");
            if (filter.isIncludeProjectDetails()) {
                contract.setProjectName((String) result[19]);
                contract.setProjectCode((String) result[20]);
            }
            if (filter.isIncludeSettings()) {
                contract.setSettings(SettingsUtil.getSettingsResponseList(settingsMap.get(contract.getId())));
            }
            contracts.add(contract);
        });
        return contracts;
    }

    public Map<UUID, Map<String, String>> getContractSettingsMap(List<Object[]> contracts) {
        return settingsService.getSettings(SettingsEnum.ObjectType.contract.name(), contracts.stream().map(entry -> (UUID) entry[0]).collect(Collectors.toList()));
    }

    @NotNull
    private Query generateContractsQuery(FilterContractInput filter, String baseQueryStr, String orderByClause) {
        StringBuilder baseQuery = new StringBuilder().append(baseQueryStr);
        Set<String> paramNames = new HashSet<>();
        if (filter.getSearch() != null) {
            boolean isWildcharexists = SQLSearchUtil.isWildcardCharExists(filter.getSearch());
            baseQuery.append(" and (lower(c.name) like :search");
            if (isWildcharexists) {
                baseQuery.append(SQLSearchUtil.escapeClause);
            }
            baseQuery.append(" or lower(c.code) like :search");
            if (isWildcharexists) {
                baseQuery.append(SQLSearchUtil.escapeClause);
            }
            baseQuery.append(" )");
            paramNames.add(SEARCH);
        } else {
            if (filter.getName() != null) {
                if (filter.getName().getContains() != null) {
                    baseQuery.append(" and c.name like :nameContains");
                    if (SQLSearchUtil.isWildcardCharExists(filter.getName().getContains())) {
                        baseQuery.append(SQLSearchUtil.escapeClause);
                    }
                    paramNames.add(NAME_CONTAINS);
                }
                if (filter.getName().getEq() != null) {
                    baseQuery.append(" and c.name = :nameEq");
                    paramNames.add(NAME_EQ);
                }
            }
            if (filter.getOwner() != null) {
                if (filter.getOwner().getContains() != null) {
                    baseQuery.append(" and c.owner like :ownerContains");
                    if (SQLSearchUtil.isWildcardCharExists(filter.getOwner().getContains())) {
                        baseQuery.append(SQLSearchUtil.escapeClause);
                    }
                    paramNames.add(OWNER_CONTAINS);
                }
                if (filter.getOwner().getEq() != null) {
                    baseQuery.append(" and c.owner = :ownerEq");
                    paramNames.add(OWNER_EQ);
                }
            }
            if (filter.getCode() != null) {
                if (filter.getCode().getContains() != null) {
                    baseQuery.append(" and c.code like :codeContains");
                    if (SQLSearchUtil.isWildcardCharExists(filter.getCode().getContains())) {
                        baseQuery.append(SQLSearchUtil.escapeClause);
                    }
                    paramNames.add(CODE_CONTAINS);
                }
                if (filter.getCode().getEq() != null) {
                    baseQuery = baseQuery.append(" and c.code = :codeEq");
                    paramNames.add(CODE_EQ);
                }
            }
        }
        if (filter.getProjectId() != null) {
            baseQuery.append(" and c.projectId = :projectId");
            paramNames.add(PROJECT_ID);
        }

        if (!authContextProvider.isApplicationAdmin()) {
            baseQuery.append(" AND pm.status = :memberStatus AND pm.otdsUserId = :otdsUserId "
                    + "AND (cm.userId = :otdsUserId OR pm.roleName = 'Administrator')");
            paramNames.add(MEMBER_STATUS);
            paramNames.add(OTDS_USER_ID);
        }

        // add order by clause
        baseQuery.append(orderByClause);

        //Create query and then set parameters.
        Query contractQuery = entityManager.createQuery(baseQuery.toString());
        setQueryParams(filter, paramNames, contractQuery);
        return contractQuery;
    }

    private void setQueryParams(FilterContractInput filter, Set<String> paramNames, Query contractQuery) {
        contractQuery.setParameter(SUBSCRIPTION_ID, UUID.fromString(authContextProvider.getSubscriptionId()));
        paramNames.forEach(paramName -> {
            switch (paramName) {
                case SEARCH:
                    contractQuery.setParameter(SEARCH, '%' + SQLSearchUtil.replaceWildcards(filter.getSearch().toLowerCase()) + '%');
                    break;
                case NAME_CONTAINS:
                    contractQuery.setParameter(NAME_CONTAINS, '%' + SQLSearchUtil.replaceWildcards(filter.getName().getContains()) + '%');
                    break;
                case NAME_EQ:
                    contractQuery.setParameter(NAME_EQ, filter.getName().getEq());
                    break;
                case OWNER_CONTAINS:
                    contractQuery.setParameter(OWNER_CONTAINS, '%' + SQLSearchUtil.replaceWildcards(filter.getOwner().getContains()) + '%');
                    break;
                case OWNER_EQ:
                    contractQuery.setParameter(OWNER_EQ, filter.getOwner().getEq());
                    break;
                case CODE_CONTAINS:
                    contractQuery.setParameter(CODE_CONTAINS, '%' + SQLSearchUtil.replaceWildcards(filter.getCode().getContains()) + '%');
                    break;
                case CODE_EQ:
                    contractQuery.setParameter(CODE_EQ, filter.getCode().getEq());
                    break;
                case PROJECT_ID:
                    contractQuery.setParameter(PROJECT_ID, UUID.fromString(filter.getProjectId().getEq()));
                    break;
                case MEMBER_STATUS:
                    contractQuery.setParameter(MEMBER_STATUS, UserStatus.ACTIVE.getValue());
                    break;
                case OTDS_USER_ID:
                    contractQuery.setParameter(OTDS_USER_ID, UUID.fromString(authContextProvider.getOtdsUserId()));
                    break;
            }
        });
    }

    public List<CountPerProject> getContractCountsPerProject() {
        if (authContextProvider.isApplicationAdmin()) {
            return contractRepository.findContractCountsPerProject(UUID.fromString(authContextProvider.getSubscriptionId()),
                    UUID.fromString(authContextProvider.getTenantId()));
        }
        return contractRepository.findContractCountsPerProject(UUID.fromString(authContextProvider.getOtdsUserId()),
                UUID.fromString(authContextProvider.getSubscriptionId()), UUID.fromString(authContextProvider.getTenantId()));
    }

    /**
     * Returns contract counts for a batch of project IDs in a single query.
     * Projects with zero contracts will have a count of 0 in the result map.
     *
     * @param projectIds list of project IDs to fetch counts for
     * @return map of projectId to contract count
     */
    public Map<UUID, Long> getContractCountsForProjects(List<UUID> projectIds) {
        if (projectIds == null || projectIds.isEmpty()) {
            return Collections.emptyMap();
        }
        List<CountPerProject> counts;
        if (authContextProvider.isApplicationAdmin()) {
            counts = contractRepository.findContractCountsByProjectIds(projectIds);
        } else {
            counts = contractRepository.findContractCountsByProjectIds(
                    UUID.fromString(authContextProvider.getOtdsUserId()), projectIds);
        }
        Map<UUID, Long> countsMap = counts.stream()
                .collect(Collectors.toMap(CountPerProject::getProjectId, CountPerProject::getCount));
        // ensure every requested project has an entry (0 if no contracts)
        projectIds.forEach(id -> countsMap.putIfAbsent(id, 0L));
        return countsMap;
    }

    public Contract getContractById(UUID contractId) throws ObjectNotFoundException {
        return getContractById(contractId, false);
    }

    /**
     * Returns actual contract Id using legacy contract Id (I.e. Id of v2)
     * @param legacyId
     * @return
     */
    public Contract getContractByLegacyId(String legacyId) throws ObjectNotFoundException {
        //Validate internalAPIKey header with the current application's internalAPIKey.
        Utils.validateInternalAPIKey(serviceInternalAPIKey, authContextProvider);
        Contract contract = contractRepository.findByLegacyIdAndSubscriptionIdAndTenantId(legacyId, UUID.fromString(authContextProvider.getSubscriptionId()), UUID.fromString(authContextProvider.getTenantId()))
                .orElseThrow(() -> new ObjectNotFoundException("Contract", legacyId));
        return contract;
    }

    public Contract getContractById(UUID contractId, Boolean includeSettings) throws ObjectNotFoundException {
        Contract contract = contractRepository.findById(contractId).orElseThrow(() -> new ObjectNotFoundException(Contract.class.getSimpleName(), contractId));
        if (includeSettings!=null && includeSettings) {
            try {
                Settings settings = settingsService.getObjectSettings(SettingsEnum.ObjectType.contract.name(), contractId);
                contract.setSettings(SettingsUtil.getSettingsResponseList(SettingsUtil.jsonToMap(settings.getSettings())));
            } catch (ObjectNotFoundException e) {
                log.warn(e.getMessage());
            }
        }
        return contract;
    }

    public List<Contract> getContractsByProjectIdAndOrgName(UUID projectId, String orgName) {
        return contractRepository.findAllByProjectIdAndOwner(projectId, orgName);
    }

    public List<Contract> getContractsByProjectId(UUID projectId) {
        return contractRepository.findAllByProjectId(projectId);
    }

    /**
     * Returns count of contracts for a given project, optionally filtered by search term.
     * Uses the same query logic as getContracts to ensure consistent results.
     *
     * @param projectId the project id
     * @param search optional search term to filter by contract name or code
     * @return count of contracts
     */
    public long getContractCountByProjectId(UUID projectId, String search) {
        FilterContractInput filter = new FilterContractInput();
        FilterIdInput projectIdFilter = new FilterIdInput();
        projectIdFilter.setEq(projectId.toString());
        filter.setProjectId(projectIdFilter);
        if (search != null && !search.isBlank()) {
            filter.setSearch(search);
        }
        Query countQuery = generateContractsQuery(filter, CONTRACTS_COUNT_QUERY, "");
        return (long) countQuery.getSingleResult();
    }

    /**
     * Events class to perform event operations.
     */
    public class Events {
        public void raiseEvent(EventType eventType, UUID subjectId, Payload payload, String userName,
                               String userId, UUID projectId, String subscriptionId, String tenantId) {
            eventPublisher.publish(
                    new Event(eventType.getValue(), subjectId, userName,
                            UUID.fromString(userId), projectId, UUID.fromString(subscriptionId), UUID.fromString(tenantId))
                            .withPayload(payload));

        }
    }

